SourceCode.Declaration:
/// <summary>
/// Chain of Command extension on <c>LogisticsPostalAddress</c> to detect when a customer's
/// primary postal address city or country/region changes and enqueue the linked <c>CustTable</c>.
/// </summary>
[ExtensionOf(tableStr(LogisticsPostalAddress))]
public final class UTCSFLogisticsPostalAddress_Extension
{
}

Method.Source:
private static boolean isPrimaryPartyLocation(LogisticsLocationRecId _locationRecId)
{
    if (!_locationRecId)
    {
        return false;
    }

    DirPartyLocation dirPartyLocation;
    select firstonly RecId from dirPartyLocation
        where dirPartyLocation.Location  == _locationRecId
           && dirPartyLocation.IsPrimary == NoYes::Yes;

    return dirPartyLocation.RecId != 0;
}

public void insert()
{
    boolean hasAddressFields = (this.City != '' || this.CountryRegionId != '');

    next insert();

    if (hasAddressFields && this.Location && UTCSFLogisticsPostalAddress_Extension::isPrimaryPartyLocation(this.Location))
    {
        UTCSFCustomerChangeHandler::tryEnqueueByLocationRecId(this.Location);
    }
}

public void update()
{
    LogisticsPostalAddress origAddress = this.orig();

    boolean hasAddressChange = (this.City            != origAddress.City
                             || this.CountryRegionId != origAddress.CountryRegionId);

    next update();

    if (hasAddressChange && this.Location && UTCSFLogisticsPostalAddress_Extension::isPrimaryPartyLocation(this.Location))
    {
        UTCSFCustomerChangeHandler::tryEnqueueByLocationRecId(this.Location);
    }
}

public void delete()
{
    LogisticsLocationRecId locationRecId = this.Location;
    boolean wasPrimary = UTCSFLogisticsPostalAddress_Extension::isPrimaryPartyLocation(locationRecId);

    next delete();

    if (wasPrimary && locationRecId)
    {
        UTCSFCustomerChangeHandler::tryEnqueueByLocationRecId(locationRecId);
    }
}
